SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM subjects WHERE code IN ('CNTT', 'KT', 'NN', 'DDT', 'CK');
UPDATE subjects SET is_active = 1 WHERE is_active = 0;
INSERT INTO subjects (code, name, description, is_active)
    VALUES ('KOR111', 'Elementary Korean 1 — Tiếng Hàn sơ cấp 1', 'Khóa học làm quen với bảng chữ cái Hangeul, phát âm, từ vựng và cấu trúc ngữ pháp cơ bản hàng ngày.', 1)
    ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), is_active = 1;
INSERT INTO subjects (code, name, description, is_active)
    VALUES ('KOR122', 'Elementary Korean 2 — Tiếng Hàn sơ cấp 2', 'Phát triển kỹ năng giao tiếp tiếng Hàn sơ cấp trong các tình huống sinh hoạt, mua sắm, hỏi đường, thời tiết.', 1)
    ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), is_active = 1;
INSERT INTO subjects (code, name, description, is_active)
    VALUES ('KOR211', 'Pre-Intermediate Korean 1 — Tiếng Hàn sơ trung cấp 1', 'Nâng cao năng lực ngữ pháp, từ vựng sinh hoạt mở rộng và hội thoại tiếng Hàn theo chủ đề.', 1)
    ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), is_active = 1;
INSERT INTO subjects (code, name, description, is_active)
    VALUES ('KOR222', 'Pre-Intermediate Korean 2 — Tiếng Hàn sơ trung cấp 2', 'Luyện tập diễn đạt suy nghĩ, cảm xúc, viết đoạn văn ngắn và nghe hiểu tin tức đời sống.', 1)
    ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), is_active = 1;
INSERT INTO subjects (code, name, description, is_active)
    VALUES ('KOR311', 'Intermediate Korean 1 — Tiếng Hàn trung cấp 1', 'Hàn ngữ trung cấp học thuật, phân tích đoạn văn và thảo luận văn hóa, xã hội Hàn Quốc.', 1)
    ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), is_active = 1;
INSERT INTO subjects (code, name, description, is_active)
    VALUES ('KOR322', 'Intermediate Korean 2 — Tiếng Hàn trung cấp 2', 'Rèn luyện kỹ năng viết luận ngắn, thuyết trình và nghe hiểu các đoạn hội thoại chuyên sâu.', 1)
    ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), is_active = 1;
INSERT INTO subjects (code, name, description, is_active)
    VALUES ('KOR411', 'Advanced Korean 1 — Tiếng Hàn cao cấp 1', 'Nâng cao vốn từ vựng học thuật, thành ngữ, quán dụng ngữ và diễn đạt tư duy phản biện.', 1)
    ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), is_active = 1;
INSERT INTO subjects (code, name, description, is_active)
    VALUES ('KOR422', 'Advanced Korean 2 — Tiếng Hàn cao cấp 2', 'Chuyên đề biên phiên dịch, đàm phán thương mại và nghiên cứu văn hóa kinh tế Hàn Quốc.', 1)
    ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), is_active = 1;
INSERT INTO subjects (code, name, description, is_active)
    VALUES ('TOP301', 'TOPIK II Prep (Level 3-4) — Luyện thi TOPIK II Trung cấp', 'Chiến thuật làm bài thi TOPIK II kỹ năng Đọc, Nghe và Viết câu 51-53 đạt chuẩn Level 3 & 4.', 1)
    ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), is_active = 1;
INSERT INTO subjects (code, name, description, is_active)
    VALUES ('TOP401', 'TOPIK II Master (Level 5-6) — Luyện thi TOPIK II Cao cấp', 'Chinh phục điểm cao TOPIK II, chuyên sâu kỹ năng Viết nghị luận câu 54 và phân tích Đọc hiểu nâng cao.', 1)
    ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), is_active = 1;
INSERT INTO subjects (code, name, description, is_active)
    VALUES ('KOR_BIZ', 'Business Korean — Tiếng Hàn thương mại & Doanh nghiệp', 'Giao tiếp trong môi trường doanh nghiệp Hàn Quốc, viết email, đàm phán và thuyết trình kinh doanh.', 1)
    ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), is_active = 1;
INSERT INTO subjects (code, name, description, is_active)
    VALUES ('KOR_TRAN', 'Korean Translation & Interpretation — Biên phiên dịch Hàn - Việt', 'Kỹ thuật dịch song ngữ Hàn - Việt, xử lý thuật ngữ chuyên ngành kinh tế, văn hóa và công nghệ.', 1)
    ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), is_active = 1;
