INSERT INTO lessons (section_id, title, display_order, status, content_richtext, content_type, created_by)
            SELECT sec.id, 'Bài 1: Cấu trúc câu và từ vựng trọng tâm', 1, 'PUBLISHED', '<h2>Bài 1: Cấu trúc câu và từ vựng trọng tâm</h2><p>Chào mừng các bạn đến với Bài 1: Cấu trúc câu và từ vựng trọng tâm thuộc lớp <strong>KOR111 - chinhcd2</strong>.</p><p>Nội dung bài học bao gồm từ vựng chuyên ngành, ngữ pháp ứng dụng và bài tập phản xạ tương tác trực tiếp.</p>', 'RICHTEXT', c.lecturer_id
            FROM sections sec
            JOIN classes c ON sec.class_id = c.id
            WHERE c.name = 'KOR111 - chinhcd2' AND sec.title = 'Chương 1: Khởi động & Nền tảng ngữ pháp'
            AND NOT EXISTS (SELECT 1 FROM lessons WHERE section_id = sec.id AND title = 'Bài 1: Cấu trúc câu và từ vựng trọng tâm');
