INSERT IGNORE INTO test_attempts (test_id, user_id, status, score, total_points, correct_count, total_questions, submitted_at, time_spent_seconds)
        SELECT t.id, e.user_id, 'SUBMITTED', 85.00, 100.00, 12, 15, NOW() - INTERVAL 1 DAY, 1200
        FROM tests t
